#wemd {
  padding: 0 8px;
  color: #282a36;
  background: #fbf8ff;
  font-family: -apple-system,BlinkMacSystemFont,'PingFang SC','Microsoft YaHei',Arial,sans-serif;
  font-size: 16px;
  line-height: 1.8;
  letter-spacing: 0px;
  overflow-wrap: break-word;
}
#wemd p { margin: 16px 0; padding: 0px 0; color: #282a36; line-height: 1.8; text-align: justify; }
#wemd h1 { margin: 40px 0 30px; color: #282a36; line-height: 1.45;  }
#wemd h1 .content { font-size: 24px; font-weight: bold; letter-spacing: 0px;  }
#wemd h2 { margin: 30px 0 18px; color: #282a36; line-height: 1.45;  }
#wemd h2 .content { font-size: 20px; font-weight: bold; letter-spacing: 0px; display:inline-block;padding:0 4px;background:linear-gradient(to bottom, transparent 60%, #bd93f933 60%); }
#wemd h3 { margin: 24px 0 14px; color: #282a36; line-height: 1.45;  }
#wemd h3 .content { font-size: 18px; font-weight: bold; letter-spacing: 0px;  }
#wemd h4 { margin: 20px 0 10px; color: #bd93f9; line-height: 1.45;  }
#wemd h4 .content { font-size: 16px; font-weight: bold; letter-spacing: 0px;  }
#wemd strong { color: #bd93f9; font-weight: 700; }
#wemd em { color: inherit; font-style: italic; }
#wemd del { color: #999999; text-decoration: line-through; }
#wemd u { text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: currentColor; text-underline-offset: .18em; }
#wemd mark { padding: 0 2px; border-radius: 2px; color: inherit; background: #fff5b1; }
#wemd a { color: #bd93f9; text-decoration: none; border-bottom: 1px solid #bd93f9; word-break: break-all; }
#wemd blockquote { margin: 16px 0; padding: 12px 16px; color: #6f6680; background: #282a36; border:4px solid #bd93f9;border-radius:8px; }
#wemd blockquote p { margin: 0; color: #6f6680; font-size: 16px; line-height: 1.6; }
#wemd ul, #wemd ol { margin: 16px 0; padding-left: 20px; color: #282a36; }
#wemd ul { list-style-type: disc; font-size: inherit; }
#wemd ul ul { list-style-type: circle; }
#wemd ol { list-style-type: decimal; font-size: inherit; }
#wemd ol ol { list-style-type: lower-alpha; }
#wemd li { margin: 6px 0; line-height: 1.8; }
#wemd li::marker { color: #bd93f9; }
#wemd code { padding: 2px 5px; border-radius: 4px; color: #bd93f9; background: #282a36; font-family: Menlo, Monaco, Consolas, 'Courier New', monospace; font-size: .92em; }
#wemd pre { margin: 16px 0; overflow-x: auto; border-radius: 9px; background: #282a36; color: #f8f8f2; text-align: left; }
#wemd pre.custom > .mac-sign { display: block; padding: 8px 12px 0; color: #bd93f9; line-height: 1; letter-spacing: 4px; opacity: .55; }
#wemd pre code, #wemd pre code.hljs { display: block; min-width: max-content; padding: 16px; margin: 0; overflow-x: auto; color: #f8f8f2; background: transparent; font-size: 13px; line-height: 1.65; white-space: pre; word-break: keep-all; text-align: left; letter-spacing: 0; }
#wemd .hljs { color: #f8f8f2; } #wemd .hljs-comment { color: #6272a4; } #wemd .hljs-keyword { color: #ff79c6; } #wemd .hljs-string { color: #f1fa8c; } #wemd .hljs-title { color: #50fa7b; }
#wemd table { width: 100%; margin: 16px 0; border-collapse: collapse; font-size: .92em; }
#wemd th, #wemd td { padding: 8px 12px; border: 1px solid #d9ccef; text-align: left; }
#wemd th { color: #282a36; background: #282a36; font-weight: 700; }
#wemd tr:nth-child(even) { background: rgba(0,0,0,.018); }
#wemd img { display: block; max-width: 100%; height: auto; margin: 20px auto; border-radius: 6px; box-shadow: 0 4px 12px rgba(0,0,0,.12); }
#wemd figcaption { margin-top: 6px; color: #6f6680; font-size: 14px; text-align: center; }
#wemd hr { margin: 22px auto; border: 0; border-top: 1px solid #d9ccef; }
#wemd .footnote-word, #wemd .footnote-ref { color: #bd93f9; font-weight: 700; }
#wemd .footnote-item p { color: #6f6680; font-size: 12px; }

