#wemd table { width: 100%; margin: 20px 0; border-collapse: collapse; font-size: .92em; }
#wemd th, #wemd td { padding: 8px 12px; border: 1px solid #e0e7e8; text-align: left; }
#wemd th { color: #20282d; background: #f6f8f8; font-weight: 700; }
#wemd tr:nth-child(even) { background: rgba(0,0,0,.018); }
#wemd img { display: block; max-width: 100%; height: auto; margin: 24px auto; border-radius: 4px; box-shadow: none; }
#wemd figcaption { margin-top: 6px; color: #6c777c; font-size: 14px; text-align: center; }
#wemd hr { margin: 26px auto; border: 0; border-top: 1px solid #e0e7e8; }
#wemd .footnote-word, #wemd .footnote-ref { color: #3f5f73; font-weight: 700; }
#wemd .footnote-item p { color: #6c777c; font-size: 12px; }
